MEGC 500 Wc + APS DS3H + batterie 15,63 kWh — 12 kWc","marque":"DMEGC / APS / RENON Xtreme LV","reference":"KIT-PV-12-BAT","description":"Kit autoconsommation photovoltaïque avec panneaux de 500 Wc, micro-onduleurs APS DS3H et stockage batterie, selon le tarif fournisseur d’août 2026.","unite":"forfait","tva":20,"prix_ttc_source":55900,"achat_materiel_ht":16700,"pose_ht":5650,"caracteristiques":{"puissance_pv_kWc":12,"nombre_panneaux_500Wc":24,"puissance_unitaire_panneau_Wc":500,"micro_onduleur":"APS DS3H","marque_panneau":"DMEGC","capacite_batterie_kWh_indiquee_source":15.63,"source_tarif":"Fichier Excel concessionnaire — onglet TARIF 2026 STOKAGE VICTRON","prix_inclut_pose":true,"note_verification":"Le fichier source indique 15,63 kWh pour les kits 12 et 18 kWc ; valeur conservée telle quelle, à confirmer (les lignes précédentes indiquent 15,36 kWh)."}},{"categorie":"photovoltaique","nom":"Kit photovoltaïque DMEGC 500 Wc + APS DS3H + batterie 15,63 kWh — 18 kWc","marque":"DMEGC / APS / RENON Xtreme LV","reference":"KIT-PV-18-BAT","description":"Kit autoconsommation photovoltaïque avec panneaux de 500 Wc, micro-onduleurs APS DS3H et stockage batterie, selon le tarif fournisseur d’août 2026.","unite":"forfait","tva":20,"prix_ttc_source":75000,"achat_materiel_ht":21800,"pose_ht":7900,"caracteristiques":{"puissance_pv_kWc":18,"nombre_panneaux_500Wc":36,"puissance_unitaire_panneau_Wc":500,"micro_onduleur":"APS DS3H","marque_panneau":"DMEGC","capacite_batterie_kWh_indiquee_source":15.63,"source_tarif":"Fichier Excel concessionnaire — onglet TARIF 2026 STOKAGE VICTRON","prix_inclut_pose":true,"note_verification":"Le fichier source indique 15,63 kWh pour les kits 12 et 18 kWc ; valeur conservée telle quelle, à confirmer (les lignes précédentes indiquent 15,36 kWh)."}},{"categorie":"combles","nom":"Isolation combles perdus soufflée — ISOVER ISOLENE 4 R7","marque":"ISOVER","reference":"ISOLENE 4","description":"Fourniture et mise en œuvre d’une isolation thermique soufflée des combles perdus en laine de verre.","unite":"m2","tva":20,"prix_ttc_source":null,"achat_materiel_ht":null,"pose_ht":null,"caracteristiques":{"type_isolant":"Laine de verre soufflée","epaisseur_mm":330,"resistance_thermique_R_m2K_W":7,"certification_acermi":"05/D/018/404","normes_evaluation_R":"NF EN 12664 / NF EN 12667 / NF EN 12939 (selon devis source)","reference_fiche_cee_source":"BAR-EN-101","details_pose":["Traitement du contour de trappe","Isolation de la trappe","Repères de hauteur","Respect des distances de sécurité autour des appareils produisant de la chaleur","Suspension de VMC"],"prix_a_renseigner":true,"source_technique":"Devis fourni par Reno Soluces; surface et montant du chantier exemple non repris comme prix catalogue"}}]'::jsonb)
  LOOP
    v_ttc := NULLIF(p->>'prix_ttc_source','')::numeric;
    v_tva := COALESCE(NULLIF(p->>'tva','')::numeric,20);
    v_ht := CASE WHEN v_ttc IS NULL THEN 0 ELSE round(v_ttc/(1+v_tva/100),2) END;
    v_car := COALESCE(p->'caracteristiques','{}'::jsonb);

    SELECT id INTO v_id FROM catalogue_produits
    WHERE categorie = p->>'categorie'
      AND ((COALESCE(p->>'reference','') <> '' AND reference = p->>'reference') OR lower(nom)=lower(p->>'nom'))
    ORDER BY CASE WHEN reference = p->>'reference' AND COALESCE(p->>'reference','') <> '' THEN 0 ELSE 1 END
    LIMIT 1;

    IF v_id IS NULL THEN
      INSERT INTO catalogue_produits (
        entreprise_id,categorie,nom,marque,reference,description,caracteristiques,
        prix_unitaire_ht,unite,tva_taux,eligible_mpr,eligible_cee,fiche_cee,actif
      ) VALUES (
        v_entreprise,p->>'categorie',p->>'nom',COALESCE(p->>'marque',''),COALESCE(p->>'reference',''),
        COALESCE(p->>'description',''),v_car,v_ht,COALESCE(p->>'unite','unite'),v_tva,false,false,'',true
      );
    ELSE
      UPDATE catalogue_produits SET
        nom = p->>'nom',
        marque = COALESCE(NULLIF(p->>'marque',''),marque),
        reference = COALESCE(NULLIF(p->>'reference',''),reference),
        description = COALESCE(NULLIF(p->>'description',''),description),
        caracteristiques = COALESCE(caracteristiques,'{}'::jsonb) || v_car,
        prix_unitaire_ht = CASE WHEN v_ttc IS NULL THEN prix_unitaire_ht ELSE v_ht END,
        unite = COALESCE(NULLIF(p->>'unite',''),unite),
        tva_taux = CASE WHEN v_ttc IS NULL THEN tva_taux ELSE v_tva END,
        actif = true
      WHERE id = v_id;
    END IF;
    v_id := NULL;
  END LOOP;
END $$;
